/* ---------- L3M3 — What isolation does not solve ---------- */
function renderC21NotFix(){return c21P('iri',
  'The most common mistake after successful containment is relief. The device is isolated, the alerts went quiet, so it is done – and this is exactly where incidents come back to life. Isolation solves the <b>spread</b>, but leaves three things untouched. First, the <b>cause</b>: you still do not know how it got there. If it was an email attachment, nothing stops someone opening the same attachment on another computer tomorrow. If it was a vulnerable service exposed outward, it is still sitting out there. Second, <b>the other devices</b>: an attacker rarely stops at the first machine. Before you isolated it, they may long have been elsewhere – so containment is followed by a check whether the same pattern shows up elsewhere, typically in the connections overview and in the log. And third, <b>persistent access</b>: an added account, a changed firewall rule, a redirected DNS record – changes the attacker made while they still controlled the device, before the isolation. Quarantining one computer does not remove them and they keep working. The practical consequence: after isolation do not take a break but <b>go straight on to the investigation</b> – precisely because quarantine stopped the clock and you now have room. And one more unpleasant lesson better read here than lived: <b>a compromised device does not return to the network merely because it went quiet</b>. It returns after remediation – cleaned or reinstalled, with changed passwords and a check that it will not start again. That is what the Remediation and recovery lesson is about.',
  [['the entry cause','the way it got in; isolation leaves it untouched and tomorrow it works again.'],['persistent access','an added account, a changed rule, a redirected record – quarantining one machine does not remove them.']])
  +courseCTA('iriTask','Stop the spread in a compromised network with quarantine and check what isolation solved and what not: the containment task.','Open the task');}
function mountC21NotFix(){c21Mount('iri',[
  {glow:c21g('pc','--muted')+c21g('sw','--muted'),dyn:c21lbl('the device is isolated, alerts went quiet – done?','--muted'),cap:'The device is isolated and the alerts went quiet. Here people feel relief – and exactly here incidents come back to life.'},
  {glow:c21g('net','--red')+c21g('fw','--red')+c21g('srv','--red'),dyn:c21pkt('M 600 160 L 320 160 L 470 255','--red','2.0s')+c21lbl('the cause stayed: the exposed service is still out','--red'),cap:'The <b>cause</b> stayed untouched: the exposed vulnerable service is still out there, the same attachment can be opened elsewhere tomorrow.'},
  {glow:c21g('pc2','--amber')+c21g('sw','--amber')+c21g('fw','--amber')+c21g('srv','--amber'),dyn:c21pkt('M 58 240 L 180 160 L 320 160 L 470 255','--amber','2.1s')+c21lbl('the attacker may long have been on another device','--amber'),cap:'An attacker rarely stops at the first machine. Check whether the same pattern shows up elsewhere – in the connections overview and the log.'},
  {glow:c21g('fw','--cyan')+c21g('log','--cyan'),dyn:c21pkt('M 320 160 L 470 60','--cyan')+c21lbl('persistence: an account, a rule, a redirected record','--cyan'),cap:'And <b>persistent access</b> remains: an added account, a changed rule, a redirected record. After isolation go straight on to the investigation.'}
]);
  var b=$('iriTask');if(b)b.onclick=function(){courseTry('quar-contain');};
}
/* ---------- L4M1 — A timeline from the logs ---------- */
function renderC21Timeline(){return c21P('irj',
  'In practice, investigating an incident looks far less dramatic than expected: you assemble a <b>timeline</b>. You take individual records from syslog, from the sensor and from alerts, order them by time and look for where the story begins. The timeline has three points you always want to find. The <b>first occurrence</b>: the oldest record belonging to the incident. It is almost always earlier than you thought – the alert came on Tuesday, but the first odd connection is from Friday. The <b>turning point</b>: the moment suspicious behavior became something harmful (data sent, a setting changed, another device touched). And the <b>last activity</b>: the newest record, from which you tell whether the incident is still live. One rule helps while assembling: <b>stick to time, not to impressions</b>. When every line has an exact time, what anyone remembers stops mattering. That is exactly why the Monitoring, logging and detection course insists so much on one log server – without a shared timeline, times from different devices align badly. Expect <b>holes</b> in the timeline too. A device that sent no logs, moments when syslog was flooded, events lost on the way. Note the hole and do not pretend nothing was there – <b>unrecorded does not mean it did not happen</b>. The timeline is the most valuable output of the whole investigation: from it follow the scope, the remediation and what later goes into the post-mortem.',
  [['timeline','records from various sources ordered by time; the scope and remediation follow from it.'],['a hole in the timeline','a period with no records (missing logging, lost events); it is noted, not hidden.']]);}
function mountC21Timeline(){c21Mount('irj',[
  {glow:c21g('pc','--blue')+c21g('sw','--blue')+c21g('fw','--blue')+c21g('log','--blue'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 470 60','--blue','2.1s')+c21lbl('the first occurrence is earlier than you thought','--blue'),cap:'Look for the <b>first occurrence</b>: the oldest record belonging to the incident. It tends to be earlier than you thought – the alert is only a consequence.'},
  {glow:c21g('pc','--red')+c21g('sw','--red')+c21g('fw','--red')+c21g('srv','--red'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 470 255','--red','2.1s')+c21lbl('turning point: suspicious became harmful','--red'),cap:'The <b>turning point</b> is when suspicious behavior became harmful: data sent, a setting changed, another device touched.'},
  {glow:c21g('ids','--amber')+c21g('fw','--amber')+c21g('log','--amber'),dyn:c21pkt('M 320 275 L 320 160 L 470 60','--amber','2.0s')+c21lbl('last activity: is the incident still live?','--amber'),cap:'The <b>last activity</b> tells you whether the incident is still live. Stick to time, not impressions – the time on the line does not lie.'},
  {glow:c21g('srv','--muted')+c21g('fw','--muted'),dyn:c21lbl('note the holes: unrecorded is not the same as absent','--muted'),cap:'There will be <b>holes</b> – devices without logs, lost events. Note them: <b>unrecorded does not mean it did not happen</b>.'}
]);}
/* ---------- L4M2 — How it spread ---------- */
function renderC21Spread(){return c21P('irk',
  'The timeline says <b>when</b>. The other half of the investigation answers <b>where through</b> – and for that you look at traffic as <b>flows</b>: who talked to whom, for how long and how much moved. In the simulator you find this in the <b>connections overview</b>, which aggregates individual connections, so instead of a thousand lines you see pairs of ‘this one talks to that one’. For an investigation it is an ideal tool, because a breach almost always shows up as a <b>new pair</b> that was not there before: a work computer talking to a database it never touched; a DMZ server calling inward into the LAN; one station talking out to an address nobody else visits. Add your picture of what is normal and you have the answer to how far it got. The second thing flows give you is the <b>blast radius</b>: the real one, not the theoretical one. The theoretical radius you could compute in advance – ‘from the DMZ one can reach the database’. The real one shows in the flows: did the attacker actually look at the database, or only try and hit a rule? The difference between ‘could have’ and ‘actually was’ is decisive for the scope, because it decides which systems remediation covers and what must be reported onward. The practical procedure is simple: <b>start at the compromised device and walk the links outward</b> – who it talked to, and who they talked to. When the list stops growing, you know the incident boundary.',
  [['flow','an aggregated view of traffic: who talked to whom, for how long and how much moved.'],['the real blast radius','where the attacker actually got according to the flows – not just where they theoretically could.']])
  +courseCTA('irkTask','Find the connection that does not belong and uncover a hidden channel outward: the task ‘Catch the C2 channel on the IPS’.','Open the task');}
function mountC21Spread(){c21Mount('irk',[
  {glow:c21g('pc2','--green')+c21g('sw','--green')+c21g('fw','--green')+c21g('srv','--green'),dyn:c21pkt('M 58 240 L 180 160 L 320 160 L 470 255','--green','2.1s')+c21lbl('normal flows: pairs that always belong there','--green'),cap:'The <b>connections overview</b> aggregates traffic into pairs of ‘who talks to whom’. This is a normal flow that always belongs.'},
  {glow:c21g('pc','--red')+c21g('sw','--red')+c21g('fw','--red')+c21g('srv','--red'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 470 255','--red','2.1s')+c21lbl('a new pair that was not there before – that is a lead','--red'),cap:'A breach shows up as a <b>new pair</b>: a computer talking to a server it never touched. That is the lead you follow.'},
  {glow:c21g('pc','--amber')+c21g('sw','--amber')+c21g('fw','--amber')+c21g('net','--amber'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 600 160','--amber','2.1s')+c21lbl('and one station talks out where nobody else does','--amber'),cap:'A second typical lead: one station talks <b>out</b> to an address nobody else visits. Is something being sent right now?'},
  {glow:c21g('fw','--cyan')+c21g('srv','--cyan')+c21g('log','--cyan'),dyn:c21pkt('M 470 255 L 320 160 L 470 60','--cyan','2.0s')+c21lbl('the real blast radius: where they actually got','--cyan'),cap:'Flows give you the <b>real blast radius</b>: where the attacker actually got, not where they theoretically could. That sets the remediation scope.'}
]);
  var b=$('irkTask');if(b)b.onclick=function(){courseTry('c2-dns');};
}
/* ---------- L4M3 — What to write down ---------- */
function renderC21Notes(){return c21P('irl',
  'During an incident you work fast and only a fraction stays in your head. So you <b>write things down</b> from the start – and surprisingly it is not extra paperwork but the cheapest way to save yourself work later. Two different things get written. First, <b>findings</b>: what you saw, where and at what time. ‘14:02 – a new connection from PC to the server in the connections overview, not there before.’ Second, <b>your own steps</b>: what you did and when. ‘14:09 – PC isolated.’ The second part is underrated and later missed the most, because without it, two days on, you cannot tell what the attacker caused and what you did yourself while cleaning up. Around evidence there is a notion called <b>chain of custody</b> – a chain in which every record makes clear <b>who</b> took it, <b>when</b> and <b>what happened to it since</b>. The exact rules are a matter for lawyers and forensic specialists; you only need to grasp the principle and act on it: records are <b>copied, not edited</b>, stored away from the compromised device, and it is noted who took them. If the incident later becomes a legal matter or an insurance claim, this decides whether your material is worth anything. And one thoroughly practical piece of advice: <b>do not start with cleanup</b>. A reboot, a reinstall or deleting a suspicious file are irreversible steps that often destroy exactly what you would need an hour later. Record first, clean up after. The simulator prepares the base for you: the Syslog panel has a <b>build report</b> button – it generates the event timeline, isolated devices and observed connections, and you add your own steps.',
  [['chain of custody','the chain of care for evidence: for each record it is clear who took it, when and what happened to it.'],['logging your steps','your own actions with times; without them you cannot tell attacker from cleanup.']]);}
function mountC21Notes(){c21Mount('irl',[
  {glow:c21g('pc','--blue')+c21g('sw','--blue')+c21g('fw','--blue')+c21g('log','--blue'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 470 60','--blue','2.1s')+c21lbl('findings: what you saw, where and at what time','--blue'),cap:'Write down <b>findings</b>: what you saw, where and when. ‘14:02 – a new connection from PC to the server, not there before.’'},
  {glow:c21g('pc','--amber')+c21g('sw','--amber'),dyn:c21pkt('M 58 80 L 180 160','--amber','1.1s')+c21lbl('and above all your own steps: what you did and when','--amber'),cap:'And above all <b>your own steps</b>: ‘14:09 – PC isolated.’ Without it, two days on, you cannot tell the attacker from your own cleanup.'},
  {glow:c21g('srv','--green')+c21g('fw','--green')+c21g('log','--green'),dyn:c21pkt('M 470 255 L 320 160 L 470 60','--green','2.0s')+c21lbl('evidence is copied away from the compromised device','--green'),cap:'Evidence is <b>copied, not edited</b>, and stored away from the compromised device. It is noted who took it and when.'},
  {glow:c21g('pc','--red')+c21g('ids','--red'),dyn:c21lbl('do not start with cleanup: reboots and deletes are final','--red'),cap:'<b>Do not start with cleanup.</b> Reboots, reinstalls and deletes are irreversible and often destroy just what you will need in an hour.'}
]);}
/* ---------- L5M1 — Remove the cause, not the symptom ---------- */
function renderC21Cause(){return c21P('irm',
  'Remediation is the phase where you remove what made the incident possible. It sounds obvious, yet in practice the <b>symptom</b> is commonly removed instead of the cause – because the symptom is visible and the cause is not. The typical examples are easy to spot: the server hung, so it was rebooted; the odd connection was blocked by a firewall rule; the compromised computer was reinstalled. In all three cases what bothered you stopped being visible. But the question ‘<b>how did it get there?</b>’ stayed unanswered, and while it does, the incident returns – possibly on another device and with another symptom. A simple question helps tell them apart; ask it at every remediation step: <b>if the attacker tried the same again, would they get through?</b> If yes, you were fixing a symptom. Causes in a network tend to be boring and repetitive: a service exposed that should not have been; a missing update; a shared or default password; a rule too broad, permitting more than it should; missing segmentation that let one machine reach everywhere. The remediation is then equally boring: close, patch, narrow, separate. Remediation also includes <b>revoking persistent access</b> mentioned under containment: added accounts, changed rules, redirected records. And beware one trap: <b>do not fix blindly</b> before you know what happened. Turning off half the network ‘just in case’ is an intervention too – irreversible for the investigation and painful for operations.',
  [['symptom vs. cause','the symptom is what you see; the cause is the way it was possible – you fix the latter.'],['the remediation test','if the attacker tried the same again, would they get through? If yes, you fixed a symptom.']]);}
function mountC21Cause(){c21Mount('irm',[
  {glow:c21g('srv','--amber')+c21g('fw','--amber'),dyn:c21pkt('M 320 160 L 470 255','--amber','1.3s')+c21lbl('a reboot and a blocking rule fix only the symptom','--amber'),cap:'The server hung, so it was rebooted; the odd connection was blocked. It is out of sight – but that is a <b>symptom</b>, not the cause.'},
  {glow:c21g('net','--red')+c21g('fw','--red')+c21g('srv','--red'),dyn:c21pkt('M 600 160 L 320 160 L 470 255','--red','2.0s')+c21lbl('the exposed service: the way in is still there','--red'),cap:'The question <b>‘how did it get there?’</b> stayed. The exposed service, the missing update or the broad rule are still there.'},
  {glow:c21g('fw','--green')+c21g('net','--green'),dyn:c21pkt('M 320 160 L 600 160','--green','1.5s')+c21lbl('remediation is boring: close, patch, narrow, separate','--green'),cap:'Remediation is as boring as the cause: <b>close, patch, narrow, separate</b> – and revoke the persistent access the attacker set up.'},
  {glow:c21g('pc','--cyan')+c21g('sw','--cyan')+c21g('fw','--cyan')+c21g('srv','--cyan'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 470 255','--cyan','2.1s')+c21lbl('the test: if they tried again, would they get through?','--cyan'),cap:'At each step ask: <b>if the attacker tried the same again, would they get through?</b> If yes, you were fixing a symptom.'}
]);}
/* ---------- L5M2 — Back into service safely ---------- */
function renderC21Restore(){return c21P('irn',
  'Recovery is the return to normal – and it is the phase where the incident’s last big mistake is made: <b>everything comes back at once and unchecked</b>. A sensible procedure has four steps. First, <b>bring things back in parts</b>, in order of importance. Turn everything on at once and if something breaks you do not know what – bring them back one by one and you know immediately. Second, <b>watch while doing it</b>: after each return check the logs, the alerts and the connections overview. This is exactly where you learn whether the remediation was complete: if the old ‘who talks to whom’ pair reappears, it was not done. Third, <b>verify the network is resilient again</b>. During the incident you may have unplugged, blocked or rerouted something – and it easily happens that the network runs, but on a single path only. For this the simulator has the <b>N-1 test</b>: it removes devices one by one and shows what stops working after each failure. If after an incident the N-1 test shows new single points of failure, recovery is not over. The <b>topology check</b> serves the same purpose, finding forgotten unplugged cables or orphaned devices. And fourth, <b>check that it really works for the users</b>, not just for you on a diagram. Call the person who reported the incident and let them try what did not work. The sentence ‘it works on my side’ is the weakest possible proof of recovery.',
  [['N-1','a test that removes devices one by one and shows what stops working after each failure.'],['staged recovery','bringing services back gradually, checking logs and connections after each step.']])
  +courseCTA('irnTask','Verify no single path is left after your intervention and build a backup route: the task ‘A single point of failure’.','Open the task');}
function mountC21Restore(){c21Mount('irn',[
  {glow:c21g('pc','--green')+c21g('sw','--green')+c21g('fw','--green'),dyn:c21pkt('M 58 80 L 180 160 L 320 160','--green')+c21lbl('bring things back in parts, not all at once','--green'),cap:'<b>Bring things back in parts</b>, by importance. Turn everything on at once and if something breaks you do not know what – one by one you see it at once.'},
  {glow:c21g('srv','--blue')+c21g('fw','--blue')+c21g('log','--blue'),dyn:c21pkt('M 470 255 L 320 160 L 470 60','--blue','2.0s')+c21lbl('after each return check the logs and connections','--blue'),cap:'After each return <b>check the logs and the connections overview</b>. If the old suspicious pair reappears, the remediation was incomplete.'},
  {glow:c21g('pc2','--amber')+c21g('sw','--amber')+c21g('fw','--amber')+c21g('net','--amber'),dyn:c21pkt('M 58 240 L 180 160 L 320 160 L 600 160','--amber','2.1s')+c21lbl('N-1 test: is a single path left after the fix?','--amber'),cap:'Run the <b>N-1 test</b> and the <b>topology check</b>: the network runs, but is a single path or an unplugged cable left behind?'},
  {glow:c21g('pc2','--cyan')+c21g('sw','--cyan')+c21g('fw','--cyan')+c21g('srv','--cyan'),dyn:c21pkt('M 58 240 L 180 160 L 320 160 L 470 255','--cyan','2.1s')+c21lbl('let the person who reported it try it out','--cyan'),cap:'Finally <b>let the user</b> who reported it try. ‘It works on my side’ is the weakest possible proof of recovery.'}
]);
  var b=$('irnTask');if(b)b.onclick=function(){courseTry('spof-fix');};
}
/* ---------- L5M3 — When an incident is closed ---------- */
function renderC21Close(){return c21P('iro',
  'Incidents have a peculiar property: they often never formally end. Service runs, nobody complains, so people simply stop thinking about it – and a month later nobody remembers what was actually solved and what was not. So closing an incident is said <b>out loud</b> and has its conditions. There are four and none can be skipped. First, <b>the cause is removed</b>, not merely covered – you can answer how it got in, and that way is closed. Second, <b>the scope is known</b>: you know which devices and data were concerned, and where you are unsure you wrote it down. Third, <b>service runs normally</b> and someone other than you verified it. And fourth, <b>there is something to hand on</b>: a record exists with the timeline, a list of your steps and what remains to be done. If any condition fails, the incident is not closed – it is merely quiet, which is not the same. A special category is an incident where <b>not everything could be established</b>. That is common and no disgrace; what matters is closing it honestly: write what you know, what you do not and what risk follows. Then it is decided whether the investigation continues or the residual risk is accepted and monitoring strengthened. Closing an incident has one more function, very important for a team: <b>it is the moment when firefighting stops and thinking starts</b> – the entry into the last phase, lessons learned.',
  [['closing an incident','a stated decision with four conditions: cause, scope, service, a record to hand on.'],['residual risk','what could not be established; it is honestly recorded and monitoring is strengthened.']]);}
function mountC21Close(){c21Mount('iro',[
  {glow:c21g('net','--green')+c21g('fw','--green'),dyn:c21pkt('M 600 160 L 320 160','--green','1.5s')+c21lbl('the cause is removed, not merely covered','--green'),cap:'First condition: <b>the cause is removed</b>, not merely covered. You can say how it got in, and that way is closed.'},
  {glow:c21g('pc','--blue')+c21g('sw','--blue')+c21g('fw','--blue')+c21g('srv','--blue'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 470 255','--blue','2.1s')+c21lbl('the scope is known: which devices and which data','--blue'),cap:'Second: <b>the scope is known</b> – you know which devices and data were concerned. Where you are unsure, you wrote it down.'},
  {glow:c21g('pc2','--amber')+c21g('sw','--amber')+c21g('fw','--amber')+c21g('srv','--amber'),dyn:c21pkt('M 58 240 L 180 160 L 320 160 L 470 255','--amber','2.1s')+c21lbl('service runs and someone other than you verified it','--amber'),cap:'Third: <b>service runs normally</b> and someone other than you verified it. Fourth: a record exists that can be handed on.'},
  {glow:c21g('log','--cyan')+c21g('fw','--cyan'),dyn:c21pkt('M 320 160 L 470 60','--cyan')+c21lbl('what is unknown is recorded as residual risk','--cyan'),cap:'When not everything could be established, close it honestly: what you know, what you do not and what <b>residual risk</b> follows.'}
]);}
/* ---------- L6M1 — A blameless post-mortem ---------- */
function renderC21Post(){return c21P('irp',
  'The last phase is the one most often skipped, and yet the only one that improves the next incident. A <b>post-mortem</b> is a short meeting after closure, going through what happened and what follows. The key word is <b>blameless</b>: you do not look for who caused it, but for <b>what made it possible</b>. This is not kindness to people, it is a practical measure. When blame is sought, people stop reporting mistakes and next time you learn of an incident much later, that is, more expensively. When causes are sought, people speak openly and you find things nobody would otherwise tell you. A post-mortem has a short outline that fits half a page. <b>What happened</b> – the timeline in a few points. <b>How we found out</b> – and above all, whether it could have been found earlier; this is the most valuable question of the meeting. <b>What we did</b> – the steps, including those that did not work. <b>What we will change</b> – concrete measures, each with one name and one date. Without the last point a post-mortem is just talk. Two things have no place in one: <b>general conclusions like ‘we must be more careful’</b> (that is not a measure, it is a wish) and <b>a list of everything that could theoretically be improved</b>. Three changes that actually happen beat thirty points nobody ever opens. The When the network is down course adds one thing: <b>even an incident that ended well deserves half an hour of review</b>.',
  [['post-mortem','a short review after closing: what happened, how we found out, what we will change.'],['blameless','you look for what made it possible, not who caused it – otherwise people stop reporting.']]);}
function mountC21Post(){c21Mount('irp',[
  {glow:c21g('log','--blue')+c21g('fw','--blue'),dyn:c21pkt('M 320 160 L 470 60','--blue')+c21lbl('what happened: the timeline in a few points','--blue'),cap:'<b>What happened</b>: the timeline in a few points, assembled from logs. Not a novel – points showing the sequence suffice.'},
  {glow:c21g('ids','--amber')+c21g('fw','--amber')+c21g('log','--amber'),dyn:c21pkt('M 320 275 L 320 160 L 470 60','--amber','2.0s')+c21lbl('how we found out – and could it have been earlier?','--amber'),cap:'<b>How we found out</b> – and above all, <b>could it have been found earlier?</b> That is the meeting’s most valuable question.'},
  {glow:c21g('pc','--green')+c21g('sw','--green')+c21g('fw','--green')+c21g('srv','--green'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 470 255','--green','2.1s')+c21lbl('what we did, including steps that did not work','--green'),cap:'<b>What we did</b>, including steps that did not work. Those are the hardest to learn and nowhere else are they discussed.'},
  {glow:c21g('fw','--cyan')+c21g('net','--cyan'),dyn:c21pkt('M 320 160 L 600 160','--cyan','1.5s')+c21lbl('what we will change: each measure with a name and date','--cyan'),cap:'<b>What we will change</b>: concrete measures, each with <b>one name and one date</b>. Without that a post-mortem is just talk.'}
]);}
/* ---------- L6M2 — What to change in the network ---------- */
function renderC21Change(){return c21P('irq',
  'Measures from a post-mortem almost always fall into three groups – worth knowing in advance, because they hint where to look. The first is <b>segmentation</b>. The question: if the same happened again, would the attacker get as far? If yes, a boundary is missing. Splitting into VLANs, separating servers from user computers, a special segment for things nobody normally works with – all of that shrinks the <b>blast radius</b> and is the most effective change you can make after an incident. The second is <b>rules</b>. Walk those the incident exploited and look for permits that are too broad: ‘from anywhere’, ‘to any port’, rules without a description, rules nobody knows the reason for. Ask each the question you know from the Network security course: <b>who exactly needs this and why</b>. The third is <b>monitoring</b>. Here you ask differently: could it have been found earlier? The answer is usually to add logging where it was missing, to send to the log server from a device that was forgotten, or to build a <b>decoy</b> – a device without legitimate traffic, where every connection is a real signal. Whatever you pick, hold to one rule: <b>few changes, but finished</b>. After an incident there is an urge to rebuild the whole network, but half-done segmentation is worse than none. Pick three things, write who and by when for each – and next time you start from a better position.',
  [['segmentation','splitting the network into separate parts; the most effective change for shrinking the blast radius.'],['few, but finished','three finished changes bring more than thirty points nobody ever returns to.']]);}
function mountC21Change(){c21Mount('irq',[
  {glow:c21g('pc','--red')+c21g('sw','--red')+c21g('fw','--red')+c21g('srv','--red'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 470 255','--red','2.1s')+c21lbl('would the attacker get as far a second time?','--red'),cap:'Question number one: <b>would the attacker get as far a second time?</b> If yes, a boundary is missing in the network.'},
  {glow:c21g('sw','--green')+c21g('fw','--green')+c21g('pc','--green'),dyn:c21pkt('M 58 80 L 180 160 L 320 160','--green')+c21lbl('segmentation: a boundary shrinks the blast radius','--green'),cap:'<b>Segmentation</b>: VLANs, separating servers from users, a special segment for what nobody normally works with.'},
  {glow:c21g('fw','--amber')+c21g('net','--amber'),dyn:c21pkt('M 320 160 L 600 160','--amber','1.5s')+c21lbl('rules: look for ‘from anywhere’ and ‘any port’','--amber'),cap:'<b>Rules</b>: walk the broad ones – ‘from anywhere’, ‘any port’, no description. Ask each who exactly needs it.'},
  {glow:c21g('ids','--cyan')+c21g('fw','--cyan')+c21g('log','--cyan'),dyn:c21pkt('M 320 275 L 320 160 L 470 60','--cyan','2.0s')+c21lbl('monitoring: add logging or build a decoy','--cyan'),cap:'<b>Monitoring</b>: add logging where it was missing, or build a <b>decoy</b>. And hold the rule: few changes, but finished.'}
]);}
/* ---------- L6M3 — A readiness checklist ---------- */
function renderC21Ready(){return c21P('irr',
  'To close the course, let us sum the whole response into a list you can walk in a few minutes and that tells you where you stand <b>today</b>, not in three months. <b>Do you collect logs in one place?</b> Verify the firewall, the sensor and the servers send there too – and that it really arrives; syslog rides on UDP 514 and gets lost quietly. <b>Do you recognize what is normal?</b> Open the connections overview and walk the ‘who talks to whom’ pairs. If you see them for the first time during an incident, you have nothing to compare against. <b>Do you know who decides and whom you call?</b> Contacts and escalation thresholds belong on paper, not in one person’s head. <b>Can you isolate a device?</b> Try quarantine as a rehearsal and notice everything it stops – so you do not learn that first in a crisis. <b>Do you have configuration backups and know how they are restored?</b> A backup you never tried to restore is only a hope. <b>Does the network survive one device failing?</b> Run the N-1 test and the topology check; single points of failure are found in calm times. And the last, uncomfortable question: <b>when did you last try this?</b> A procedure nobody ever walked is not a procedure but a document. A half-hour rehearsal – ‘the server is compromised, now what?’ – finds a missing contact and missing logs more reliably than any audit. Incident response is not trained during an incident.',
  [['a rehearsal','a short calm run-through of the response; it finds missing contacts and logs before an incident does.'],['readiness','the state where logs, contacts, a map, backups and a rehearsed procedure exist before anything happens.']])
  +courseCTA('irrTask','Build defense in layers so one breach is not enough for the whole network: the task ‘Layered defense’.','Open the task');}
function mountC21Ready(){c21Mount('irr',[
  {glow:c21g('pc','--green')+c21g('sw','--green')+c21g('fw','--green')+c21g('log','--green'),dyn:c21pkt('M 58 80 L 180 160 L 320 160 L 470 60','--green','2.1s')+c21lbl('do you collect logs in one place, and do they arrive?','--green'),cap:'<b>Do you collect logs in one place?</b> And do they arrive from the firewall and the sensor too? Syslog rides on UDP 514 and gets lost quietly.'},
  {glow:c21g('pc2','--blue')+c21g('sw','--blue')+c21g('fw','--blue')+c21g('srv','--blue'),dyn:c21pkt('M 58 240 L 180 160 L 320 160 L 470 255','--blue','2.1s')+c21lbl('do you know what is normal? walk the overview','--blue'),cap:'<b>Do you know what is normal?</b> Walk the pairs in the connections overview. Seeing them first during an incident leaves nothing to compare.'},
  {glow:c21g('pc','--amber')+c21g('sw','--amber'),dyn:c21pkt('M 58 80 L 180 160','--amber','1.1s')+c21lbl('can you isolate? try quarantine as a rehearsal','--amber'),cap:'<b>Can you isolate a device?</b> Try quarantine as a rehearsal and notice everything it stops – not first in a crisis.'},
  {glow:c21g('pc2','--cyan')+c21g('sw','--cyan')+c21g('fw','--cyan')+c21g('net','--cyan'),dyn:c21pkt('M 58 240 L 180 160 L 320 160 L 600 160','--cyan','2.1s')+c21lbl('when did you last try? procedures are trained calmly','--cyan'),cap:'And the last question: <b>when did you last try this?</b> Incident response is not trained during an incident, but calmly.'}
]);
  var b=$('irrTask');if(b)b.onclick=function(){courseTry('layered-def');};
}

